const resetViewButton=document.getElementById('resetView');
const viewResetDuration=850,resetIconLead=300;
let resetFeedbackVersion=0,resetFeedbackAnimations=[];
function animateResetIcon(){
 const version=++resetFeedbackVersion;
 resetFeedbackAnimations.forEach(animation=>animation.cancel());resetFeedbackAnimations=[];
 const spin=resetViewButton.querySelector('.reset-spin-icon'),check=resetViewButton.querySelector('.reset-check-icon'),path=check.querySelector('path');
 spin.style.opacity='1';check.style.opacity='0';path.style.strokeDashoffset='1';resetViewButton.dataset.resetPhase='idle';
 if(reducedMotionPreference.matches)return;
 const animate=(element,frames,duration,fill='forwards')=>{const animation=element.animate(frames,{duration,easing:'ease-in-out',fill});resetFeedbackAnimations.push(animation);return animation.finished;};
 resetViewButton.dataset.resetPhase='rotating';
 animate(resetViewButton,[{transform:'translateY(0) scale(1)'},{transform:'translateY(2px) scale(.94)',offset:.35},{transform:'translateY(0) scale(1)'}],180,'none').catch(()=>{});
 (async()=>{
  try{
   await animate(spin,[{transform:'rotate(0deg)'},{transform:'rotate(-360deg)'}],viewResetDuration-resetIconLead);
   if(version!==resetFeedbackVersion)return;
   resetViewButton.dataset.resetPhase='shrinking';
   await animate(spin,[{transform:'rotate(-360deg) scale(1)',opacity:1},{transform:'rotate(-360deg) scale(0)',opacity:0}],160);
   if(version!==resetFeedbackVersion)return;
   resetViewButton.dataset.resetPhase='confirming';check.style.opacity='1';
   await animate(path,[{strokeDashoffset:1},{strokeDashoffset:0}],320);
   await animate(check,[{opacity:1},{opacity:1}],120);
   while(resetAnimation&&version===resetFeedbackVersion)await new Promise(requestAnimationFrame);
   if(version!==resetFeedbackVersion)return;
   resetViewButton.dataset.resetPhase='returning';
   await animate(path,[{strokeDashoffset:0},{strokeDashoffset:1}],320);
   if(version!==resetFeedbackVersion)return;
   check.style.opacity='0';
   await animate(spin,[{transform:'rotate(-360deg) scale(0)',opacity:0},{transform:'rotate(-360deg) scale(1)',opacity:1}],200);
   if(version!==resetFeedbackVersion)return;
   resetFeedbackAnimations.forEach(animation=>animation.cancel());resetFeedbackAnimations=[];
   spin.style.opacity='1';path.style.strokeDashoffset='1';resetViewButton.dataset.resetPhase='idle';
  }catch{}
 })();
}
